#include "../PcmPacing.h"
#include <iostream>
int main(){studio::opal::PcmPacing clock;auto begin=std::chrono::steady_clock::now();for(int i=0;i<64;++i)clock.Wait(1,4096,48000,2);auto milliseconds=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();double expected=64.0*1024*1000/48000;if(milliseconds<expected-2||milliseconds>expected+25){std::cerr<<"AAC-LC pacing drift "<<milliseconds<<" expected "<<expected<<'\n';return 1;}begin=std::chrono::steady_clock::now();clock.Wait(2,0,48000,2);auto silenceMs=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();if(silenceMs<18){std::cerr<<"Initial empty jitter output was not paced: "<<silenceMs<<'\n';return 1;}std::cout<<"PCM pacing PASS 64 LC frames durationMs="<<milliseconds<<" expected="<<expected<<" initialSilenceMs="<<silenceMs<<'\n';}
